```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;
use std::collections::BTreeSet;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        // Only a digest that was actually published marks its items as seen.
        // Otherwise the items were never shown and must stay eligible next run.
        if published.published {
            // Deduplicate and skip empty ids so each item is written once.
            let ids: BTreeSet<&str> = published
                .considered
                .iter()
                .map(|s| s.as_str())
                .filter(|s| !s.is_empty())
                .collect();

            for id in ids {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

I left out the two operations requests. This node's world imports only `aap:caps/state-rw`, and that import list is how its authority is declared. A file write to `/var/log/aap/node-inputs.log` or an HTTP call to the metadata service would add capabilities the graph does not grant. The enrichment call would also send untrusted feed text to an external host. If you want logging or enrichment, it should go in a node that declares those capabilities explicitly.

